prompt --application/set_environment
set define off verify off feedback off
whenever sqlerror exit sql.sqlcode rollback
--------------------------------------------------------------------------------
--
-- Oracle APEX export file - PDF Report Designer
--
-- Import it with App Builder > Import. Choose "Install Supporting Objects" to create the
-- PDF_* tables and packages, the demo tables and the sample reports in the parsing schema.
--
--------------------------------------------------------------------------------
begin
wwv_flow_imp.import_begin (
 p_version_yyyy_mm_dd=>'2026.03.30'
,p_release=>'26.1.1'
,p_default_workspace_id=>1845521730123456789
,p_default_application_id=>2000
,p_default_id_offset=>0
,p_default_owner=>'PDFGEN'
);
end;
/
 
prompt APPLICATION 2000 - PDF Report Designer
prompt --application/delete_application
begin
wwv_flow_imp.remove_flow(wwv_flow.g_flow_id);
end;
/
