begin
wwv_flow_imp_page.create_page(
 p_id=>4
,p_name=>'Try the API'
,p_alias=>'TRY'
,p_step_title=>'Try the API'
,p_reload_on_submit=>'A'
,p_warn_on_unsaved_changes=>'N'
,p_autocomplete_on_off=>'OFF'
,p_group_id=>wwv_flow_imp.id(81000000000000008)
,p_inline_css=>'.pdfd-snippet { margin: 0; padding: 10px 12px; background: #0f1b2b; color: #e6edf7; border-radius: 6px; font: 12.5px/1.5 ui-monospace, Menlo, Consolas, monospace; white-space: pre-wrap; }'
,p_javascript_code_onload=>wwv_flow_string.join(wwv_flow_t_varchar2(
'window.pdfTry = function () {',
'  var code = $v(''P4_REPORT''), pairs = [];',
'  $v(''P4_PARAMS'').split(/\r?\n/).forEach(function (l) {',
'    var i = l.indexOf(''='');',
'    if (i > 0) { pairs.push("''" + l.slice(0, i).trim() + "'', ''" + l.slice(i + 1).trim().replace(/''/g, "''''") + "''"); }',
