wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(81000000000000150)
,p_process_sequence=>10
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Load the invoice'
,p_static_id=>'load-the-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'begin',
'  select invoice_no, to_char(invoice_date, ''DD-MON-YYYY''), to_char(due_date, ''DD-MON-YYYY''), customer_id, status, notes',
'    into :P11_INVOICE_NO, :P11_INVOICE_DATE, :P11_DUE_DATE, :P11_CUSTOMER_ID, :P11_STATUS, :P11_NOTES',
'    from pdf_demo_invoices',
'   where invoice_id = :P11_INVOICE_ID;',
'end;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'P11_INVOICE_ID'
,p_process_when_type=>'ITEM_IS_NOT_NULL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>90000000000009
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(81000000000000151)
,p_process_sequence=>20
,p_process_point=>'BEFORE_HEADER'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Defaults of a new invoice'
,p_static_id=>'defaults-of-a-new-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select ''NW/2026-27/'' || to_char(nvl(max(to_number(substr(invoice_no, -4) default null on conversion error)), 0) + 1, ''FM0000''),',
'       to_char(trunc(sysdate), ''DD-MON-YYYY''), to_char(trunc(sysdate) + 30, ''DD-MON-YYYY''), ''DUE''',
'  into :P11_INVOICE_NO, :P11_INVOICE_DATE, :P11_DUE_DATE, :P11_STATUS',
'  from pdf_demo_invoices;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>':P11_INVOICE_ID is null and :P11_INVOICE_NO is null'
,p_process_when_type=>'EXPRESSION'
,p_process_when2=>'PLSQL'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>90000000000010
);
wwv_flow_imp_page.create_page_process(
 p_id=>wwv_flow_imp.id(81000000000000152)
,p_process_sequence=>10
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Create the invoice'
,p_static_id=>'create-the-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'select nvl(max(invoice_id), 1000) + 1 into :P11_INVOICE_ID from pdf_demo_invoices;',
'insert into pdf_demo_invoices (invoice_id, invoice_no, invoice_date, due_date, customer_id, status, notes)',
'values (:P11_INVOICE_ID, :P11_INVOICE_NO, to_date(:P11_INVOICE_DATE, ''DD-MON-YYYY''), to_date(:P11_DUE_DATE, ''DD-MON-YYYY''),',
'        :P11_CUSTOMER_ID, :P11_STATUS, :P11_NOTES);'))
,p_process_clob_language=>'PLSQL'
,p_process_when_button_id=>wwv_flow_imp.id(81000000000000110)
,p_process_success_message=>'Invoice created - add its lines.'
,p_error_display_location=>'INLINE_IN_NOTIFICATION'
,p_internal_uid=>90000000000011
);
