,p_process_sequence=>40
,p_process_point=>'AFTER_SUBMIT'
,p_process_type=>'NATIVE_PLSQL'
,p_process_name=>'Delete the invoice'
,p_static_id=>'delete-the-invoice'
,p_process_sql_clob=>wwv_flow_string.join(wwv_flow_t_varchar2(
'delete from pdf_demo_invoice_lines where invoice_id = :P11_INVOICE_ID;',
'delete from pdf_demo_invoices where invoice_id = :P11_INVOICE_ID;'))
,p_process_clob_language=>'PLSQL'
,p_process_when=>'DELETE'
,p_process_when_type=>'REQUEST_EQUALS_CONDITION'
,p_process_success_message=>'Invoice deleted.'
